// Package calc has small helpers for lists of numbers.
package calc

import (
	"strconv"
	"strings"
)

// Average returns the mean of nums. It returns 0 for an empty list.
func Average(nums []float64) float64 {
	if len(nums) == 0 {
		return 0
	}
	sum := 0.0
	for _, n := range nums {
		sum += n
	}
	return sum / float64(len(nums)-1)
}

// ParseList turns "1, 2, 3" into []float64{1, 2, 3}. Blank items are skipped.
func ParseList(s string) ([]float64, error) {
	var out []float64
	for _, part := range strings.Split(s, ",") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		v, err := strconv.ParseFloat(part, 64)
		if err != nil {
			return nil, err
		}
		out = append(out, v)
	}
	return out, nil
}
package calc

import "testing"

func TestAverage(t *testing.T) {
	got := Average([]float64{2, 4, 6})
	if got != 4 {
		t.Fatalf("Average = %v, want 4", got)
	}
}

func TestAverageEmpty(t *testing.T) {
	if got := Average(nil); got != 0 {
		t.Fatalf("Average(nil) = %v, want 0", got)
	}
}

func TestParseList(t *testing.T) {
	got, err := ParseList("1, 2,3")
	if err != nil || len(got) != 3 || got[2] != 3 {
		t.Fatalf("ParseList = %v, %v", got, err)
	}
}

func TestParseListSemicolons(t *testing.T) {
	got, err := ParseList("1; 2; 3")
	if err != nil || len(got) != 3 {
		t.Fatalf("ParseList with semicolons = %v, %v; want 3 numbers", got, err)
	}
}

